/* Generated by the build. Cache name follows the script hash so a deploy replaces this worker. */
const SHELL = "kani-shell-BcZSMeT0";
const PASSAGES = "kani-passages";
const PASSAGE_LIMIT = 10;
const PRECACHE = ["/","/index.html","/manifest.webmanifest","/icons/icon-180.png","/icons/icon-192.png","/icons/icon-512.png","/assets/index-pITScrbr.css","/assets/index-BcZSMeT0.js"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(SHELL).then((cache) => cache.addAll(PRECACHE)));
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        keys
          .filter((key) => key.startsWith("kani-shell-") && key !== SHELL)
          .map((key) => caches.delete(key)),
      ))
      .then(() => self.clients.claim()),
  );
});

function isPassage(url) {
  if (url.pathname !== "/api/read") return false;
  const action = url.searchParams.get("action");
  return action === "passage" || action === "daily";
}

async function shell() {
  const cached = await caches.match("/index.html");
  if (cached) return cached;
  return new Response("", { status: 503, headers: { "Content-Type": "text/html; charset=utf-8" } });
}

async function rememberPassage(request) {
  const cache = await caches.open(PASSAGES);
  const response = await fetch(request);
  if (response.ok) {
    await cache.delete(request);
    await cache.put(request, response.clone());
    const keys = await cache.keys();
    if (keys.length > PASSAGE_LIMIT) {
      await cache.delete(keys[0]);
    }
  }
  return response;
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (isPassage(url)) {
    event.respondWith(
      rememberPassage(request).catch(async () => {
        const cache = await caches.open(PASSAGES);
        return (await cache.match(request)) || new Response("", { status: 504 });
      }),
    );
    return;
  }
  if (url.pathname.startsWith("/api/")) return;
  if (request.mode === "navigate") {
    event.respondWith(fetch(request).catch(() => shell()));
    return;
  }
  event.respondWith(
    caches.match(request).then((cached) => cached || fetch(request)).catch(() => new Response("", { status: 504 })),
  );
});
